]

n = 15
H = 9  # Horizontal line row in demo1

# Get horizontal color at each column
horizontal_colors = {}
for c in range(n):
    if demo1_input[H][c] != 0:
        horizontal_colors[c] = demo1_input[H][c]
    # If 0, look for nearby non-zero to assign
    elif c < 8:
        horizontal_colors[c] = 2  # Left part
    else:
        horizontal_colors[c] = 3  # Right part

print("Horizontal colors:", {c: horizontal_colors[c] for c in range(n)})

# Verticals: cols 3 and 9
v_colors = {3: 3, 9: 4}

# Build output
output = [[0]*n for _ in range(n)]

# Fill horizontal row
for c in range(n):
    output[H][c] = horizontal_colors[c]

# Fill verticals
for c, v_c in v_colors.items():
    h_c = horizontal_colors[c]
    for r in range(n):
        if r <= H:
            output[r][c] = h_c
        else:
            output[r][c] = v_c

# Verify against expected demo1 output
