            for j in range(cols):
                if row[j] != 0:
                    horizontal_color = row[j]
                    break
            if horizontal_color:
                break

    # Identify columns with patterns
    vertical_colors = {}
    for j in range(cols):
        # Check below H
        v_color = None
        for i in range(H + 1, rows):
            if grid[i][j] != 0:
                v_color = grid[i][j]
                break
        if v_color:
            vertical_colors[j] = v_color

    # Build output
    out = [[0] * cols for _ in range(rows)]

    # Fill horizontal pattern above and at H
    for i in range(H + 1):
        for j in range(cols):
            if grid[i][j] != 0:
                out[i][j] = horizontal_color

    # Fill full horizontal row H
    out[H] = [horizontal_color] * cols

    # Fill vertical pattern below H
    for i in range(H + 1, rows):
        for j, v_color in vertical_colors.items():
            out[i][j] = v_color

    return out

