    for row in range(H):
        if grid[row][8] != 0:
            h_color_at_8 = grid[row][8]
            break

    # Columns 3 and 8 have patterns
    cols_with_patterns = [3, 8]

    # Determine vertical colors from below row H
    v_color_at_3 = 0
    for i in range(H + 1, n_rows):
        if grid[i][3] != 0:
            v_color_at_3 = grid[i][3]
            break

