    for row in range(H):
        for col in cols_with_patterns:
            if grid[row][col] != 0:
                output[row][col] = grid[row][col]

    # Row H gets full horizontal fill
    for col in cols_with_patterns:
        output[H][col] = h_color_at_col if (h_color_at_col := (grid[H][col] if grid[H][col] else (grid[H-1][col] if H-1 >= 0 else 0))) != 0 else 4
    output[H] = [grid[H][j] if grid[H][j] else (grid[H-1][j] if H-1 >= 0 and grid[H-1][j] else 4) for j in range(15)]

