            break

    if H == 0:
        # Fallback: find row with highest non-zero count
        max_nz = 0
        for i, row in enumerate(grid):
            nz_count = sum(1 for v in row if v != 0)
            if nz_count > max_nz:
                max_nz = nz_count
                H = i

        # If still not found, use row 11 as default for this task
        if H == 0:
            H = 11

    # Find horizontal color at pattern cols 3 and 8
    # The horizontal color is what fills rows above H at these columns
    def get_h_color_at_col(col, grid, row_limit):
        for row in range(row_limit):
            val = grid[row][col]
            if val != 0:
                return val
        return 4  # default for this task

    h_color_at_3 = get_h_color_at_col(3, grid, H)
    h_color_at_8 = get_h_color_at_col(8, grid, H)

    # Find vertical colors below H at cols 3 and 8
    def get_v_color_at_col(col, grid):
        for row in range(H + 1, n_rows):
