    for row in range(H + 1):
        for col in pattern_cols:
            if grid[row][col] != 0:
                output[row][col] = h_color_at_col(col, grid, H)
            else:
                output[row][col] = h_color_at_col(col, grid, H)

    # Row H: full horizontal fill (all cols, horizontal color)
    output[H] = [h_color_at_col(j, grid, H) if grid[H][j] != 0 
