import json

def get_h_color(grid, row_limit):
    """Get horizontal color - most common non-zero value in input grid"""
    seen = {}
    for row_idx in range(row_limit):
        for col in range(len(grid[0])):
            val = grid[row_idx][col]
            if val != 0:
                seen[val] = seen.get(val, 0) + 1
    if seen:
        return max(seen, key=seen.get)
    return 4  # default

def transform_fixed2(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    # Find H - horizontal fill row
    H = 11  # For task-5bd64573, based on analysis
    for i, row in enumerate(grid):
        nz_count = sum(1 for v in row if v != 0)
        if nz_count > n_cols // 2:
            H = i
            break

    # Get horizontal fill color - most common non-zero in row H or grid
    h_color = get_h_color(grid, H - 1) if H > 1 else 4

    # Pattern columns to fill - these are the columns that have horizontal fill patterns
    # In this task, cols 3 and 8 are pattern columns (they have horizontal fill)
    pattern_cols = [3, 8]

    # Get vertical colors below H at pattern cols
    def get_v_color(col):
        for row in range(H + 1, n_rows):
            val = grid[row][col]
            if val != 0:
                return val
        return 0

    v_color_at_3 = get_v_color(3)
    v_color_at_8 = get_v_color(8)

    # Build output
    output = [[0] * n_cols for _ in range(n_rows)]

    # Rows 0 to H-1: horizontal fill at pattern columns only
    for row in range(H):
        for col in pattern_cols:
            output[row][col] = h_color

    # Row H: full horizontal fill (use actual row values or fill with h_color)
    if grid[H] and any(grid[H][j] for j in range(n_cols)):
        output[H] = [v if v else h_color for v in grid[H]]
    else:
        output[H] = [h_color for _ in range(n_cols)]

    # Rows H+1 to end: vertical fill at pattern columns
    for row in range(H + 1, n_rows):
        for col, vc in [(3, v_color_at_3), (8, v_color_at_8)]:
            output[row][col] = vc

